using System.ComponentModel;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var researchTools = new ResearchTools();

var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI agent that researches topics by searching the web and taking notes.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools =
            [
                AIFunctionFactory.Create(researchTools.SearchWeb),
                AIFunctionFactory.Create(researchTools.SaveNote),
                AIFunctionFactory.Create(researchTools.GetNotes),
            ],
        },
    });

Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        Research Agent (type 'exit')      ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

var session = await agent.CreateSessionAsync();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic: ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("exit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }

    var prompt = $"""
        Research the following topic thoroughly. Use the SearchWeb tool multiple times with
        different queries to gather diverse information. Use SaveNote to record key findings
        as you go. After researching, use GetNotes to review everything you collected, then
        provide a well-structured summary with sections and source references.

        Topic: {topic}
        """;

    Console.WriteLine();

    try
    {
        var runOptions = new ChatClientAgentRunOptions(new ChatOptions { MaxOutputTokens = 4096 });

        await foreach (var update in agent.RunStreamingAsync(prompt, session, runOptions))
        {
            if (update.Text is { Length: > 0 } text)
            {
                Console.Write(text);
            }
        }
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }

    Console.WriteLine();
    Console.WriteLine();

    if (researchTools.NoteCount > 0)
    {
        Console.ForegroundColor = ConsoleColor.DarkGray;
        Console.WriteLine($"[{researchTools.NoteCount} note(s) collected during research]");
        Console.ResetColor();
        researchTools.ClearNotes();
    }

    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

/// <summary>Tools available to the research agent for web search and note-taking.</summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _http = new();

    public int NoteCount => _notes.Count;

    [Description("Search the web for information on a query. Returns relevant search result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.WriteLine($"  🔍 Searching: {query}");
        Console.ResetColor();

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            var json = await _http.GetStringAsync(url, cancellationToken);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            if (root.TryGetProperty("Abstract", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
            {
                var source = root.TryGetProperty("AbstractSource", out var s) ? s.GetString() : "Unknown";
                results.Add($"[{source}] {abstractText}");
            }

            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                    {
                        var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : "";
                        results.Add($"• {t} ({firstUrl})");
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for '{query}'. Try rephrasing the query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note with a title and content for later reference.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("The note content with findings")] string content)
    {
        _notes.Add($"## {title}\n{content}");

        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine($"  📝 Note saved: {title}");
        Console.ResetColor();

        return $"Note '{title}' saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes to review findings before summarizing.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet. Use SaveNote to record findings.";
        }

        return $"=== Research Notes ({_notes.Count}) ===\n\n{string.Join("\n\n---\n\n", _notes)}";
    }

    public void ClearNotes() => _notes.Clear();
}

