    [Description("Search the web for information on a query. Returns relevant search result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.WriteLine($"  🔍 Searching: {query}");
        Console.ResetColor();

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            var json = await _http.GetStringAsync(url, cancellationToken);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            if (root.TryGetProperty("Abstract", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
            {
                var source = root.TryGetProperty("AbstractSource", out var s) ? s.GetString() : "Unknown";
                results.Add($"[{source}] {abstractText}");
            }

            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                    {
                        var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : "";
                        results.Add($"• {t} ({firstUrl})");
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for '{query}'. Try rephrasing the query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note with a title and content for later reference.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("The note content with findings")] string content)
    {
        _notes.Add($"## {title}\n{content}");

        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine($"  📝 Note saved: {title}");
        Console.ResetColor();

        return $"Note '{title}' saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes to review findings before summarizing.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet. Use SaveNote to record findings.";
        }

        return $"=== Research Notes ({_notes.Count}) ===\n\n{string.Join("\n\n---\n\n", _notes)}";
    }

    public void ClearNotes() => _notes.Clear();
}

